// Oudere waarnemingen bewaarden het id zonder categorie (alleen steenbekledingen).
export const schadebeeld = (id) => SCHADEBEELDEN.find((s) => s.id === id || s.id === `steenbekledingen/${id}`) ?? null;
/** Digigids-schadebeelden bij een STOWA-inspectiewijzer (nummer). */
export const bijWijzer = (nr) => SCHADEBEELDEN.filter((s) => s.wijzer !== null && String(s.wijzer) === String(nr));
/** Digigids-schadebeelden zonder inspectiewijzer: die worden als eigen schadebeeld aangeboden. */
export const zonderWijzer = () => SCHADEBEELDEN.filter((s) => s.wijzer === null);
/** Tekst van een klasse: het criterium, of anders het bijschrift bij de voorbeeldfoto's. */
export const klasseTekst = (k) => k?.criterium || (k?.beeld ?? []).join(' · ');
export const fotoUrl = (pad) => `${BRON}${pad}`;
